// Where the case screen gets the AI's combined people/vehicles/weapons and
// their pictures from.
//
// SupabaseEvidenceSource is the real one. load() calls get_case_evidence,
// which returns the same JSON shape as case_matcher.case_view(). image() and
// bytes() pull pictures from the private bucket, answer() is
// answer_entity_match, and combine() is combine_case_entities ("Person 3 is
// actually Person 1").
//
// SampleEvidenceSource serves a canned case bundled in assets/sample_case/,
// generated by running the real pipeline on test clips. It's labelled
// "Sample data" on screen. Useful for demos when there's no worker running:
//     CaseEvidenceSource.standard = SampleEvidenceSource();

import 'dart:convert';
import 'dart:ui' as ui;

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart' show rootBundle;
import 'package:flutter/widgets.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

import 'package:argus_shield/models/case_evidence.dart';

abstract class CaseEvidenceSource {
  /// The case's AI evidence, or null if there isn't any yet.
  Future<CaseEvidence?> load(int caseId);

  /// A picture to show, thumbnail or full size.
  ImageProvider image(String path);

  /// The picture's raw bytes, for downloading.
  Future<Uint8List> bytes(String path);

  /// The admin's answer to "Is this Person 2?".
  Future<void> answer(int caseId, String memberKey, {required bool yes});

  /// The one the app uses.
  static CaseEvidenceSource standard = SupabaseEvidenceSource();
}

/// A source where people/vehicles/weapons can be merged by hand. Only cases
/// support this. On a single submission each clip's entries are kept
/// separate on purpose.
abstract class EntityCombiner {
  bool get canCombine;

  /// Say [fromId] (e.g. "p3", the one you're looking at) is really [intoId]
  /// ("p1"). All its pictures move over and it gets removed. Returns the id
  /// of the combined entry, i.e. [intoId].
  Future<String> combine(int caseId, String fromId, String intoId);
}

/// The real thing: AI evidence from Supabase, pictures from the private
/// bucket. Only for admins and investigators on the case, and the database
/// and bucket policies enforce that.
class SupabaseEvidenceSource implements CaseEvidenceSource, EntityCombiner {
  static const bucket = 'submissions';

  /// [_client] is only for tests, the app uses Supabase.instance.client.
  SupabaseEvidenceSource([this._client]);

  final SupabaseClient? _client;

  // getter so this can be constructed before Supabase is initialised
  SupabaseClient get _supabase => _client ?? Supabase.instance.client;

  /// The client, for subclasses like SubmissionEvidenceSource.
  @protected
  SupabaseClient get db => _supabase;

  @override
  Future<CaseEvidence?> load(int caseId) async {
    try {
      final data =
          await _supabase.rpc('get_case_evidence', params: {'p_caseid': caseId});
      if (data == null) return null; // case doesn't exist
      final evidence =
          CaseEvidence.fromMap(Map<String, dynamic>.from(data as Map));
      // nothing analysed or merged yet, screen says "No AI analysis for this case yet."
      if (evidence.isEmpty && evidence.aiSummary.trim().isEmpty) return null;
      return evidence;
    } catch (e) {
      debugPrint('Could not load the AI evidence of case $caseId: $e');
      return null;
    }
  }

  /// Downloaded with the user's own session rather than a public/signed URL,
  /// so the bucket policies decide and links can't expire while the screen
  /// is open. Flutter's image cache keeps one copy of each.
  @override
  ImageProvider image(String path) => _BucketImage(path, bytes);

  @override
  Future<Uint8List> bytes(String path) =>
      _supabase.storage.from(bucket).download(path);

  /// memberKey is the detection id (see get_case_evidence).
  @override
  Future<void> answer(int caseId, String memberKey, {required bool yes}) async {
    final detectionId = int.tryParse(memberKey);
    if (detectionId == null) {
      throw ArgumentError('Not a detection id: $memberKey');
    }
    await _supabase.rpc('answer_entity_match',
        params: {'p_detectionid': detectionId, 'p_yes': yes});
  }

  @override
  bool get canCombine => true;

  /// Admins and assigned investigators, not on closed cases. The database
  /// checks both.
  @override
  Future<String> combine(int caseId, String fromId, String intoId) async {
    final result = await _supabase.rpc('combine_case_entities', params: {
      'p_caseid': caseId,
      'p_from': fromId,
      'p_into': intoId,
    });
    return (result is Map ? result['entity_id'] as String? : null) ?? intoId;
  }
}

/// A picture from the bucket, fetched via [load]. Keyed by path so the grid
/// and the full-size viewer share the cached image.
@immutable
class _BucketImage extends ImageProvider<_BucketImage> {
  const _BucketImage(this.path, this.load);

  final String path;
  final Future<Uint8List> Function(String path) load;

  @override
  Future<_BucketImage> obtainKey(ImageConfiguration configuration) =>
      SynchronousFuture<_BucketImage>(this);

  @override
  ImageStreamCompleter loadImage(_BucketImage key, ImageDecoderCallback decode) =>
      MultiFrameImageStreamCompleter(
        codec: _codec(decode),
        scale: 1.0,
        debugLabel: path,
      );

  Future<ui.Codec> _codec(ImageDecoderCallback decode) async {
    final data = await load(path);
    return decode(await ui.ImmutableBuffer.fromUint8List(data));
  }

  @override
  bool operator ==(Object other) => other is _BucketImage && other.path == path;

  @override
  int get hashCode => path.hashCode;
}

/// The bundled sample. Answers only live in memory while the app runs.
class SampleEvidenceSource implements CaseEvidenceSource, EntityCombiner {
  static const asset = 'assets/sample_case/case_view.json';
  static Map<String, dynamic>? _data; // static so answers survive navigating away

  Future<Map<String, dynamic>> _sample() async {
    return _data ??= Map<String, dynamic>.from(
        jsonDecode(await rootBundle.loadString(asset)) as Map);
  }

  @override
  Future<CaseEvidence?> load(int caseId) async {
    try {
      return CaseEvidence.fromMap(await _sample(), isSample: true);
    } catch (e) {
      debugPrint('Sample case evidence not available: $e');
      return null;
    }
  }

  @override
  ImageProvider image(String path) => AssetImage(path);

  @override
  Future<Uint8List> bytes(String path) async =>
      (await rootBundle.load(path)).buffer.asUint8List();

  @override
  Future<void> answer(int caseId, String memberKey, {required bool yes}) async {
    final data = await _sample();
    for (final group in ['people', 'vehicles', 'weapons']) {
      for (final raw in (data[group] as List)) {
        final entity = raw as Map;
        final questions = (entity['questions'] as List? ?? []);
        final i = questions.indexWhere((q) => (q as Map)['member_key'] == memberKey);
        if (i < 0) continue;
        final q = questions.removeAt(i) as Map;
        final crops = q['crops'] as List;
        if (yes) {
          (entity['crops'] as List).addAll(crops);
          entity['submission_count'] = ((entity['submission_count'] as num?) ?? 1) + 1;
        } else {
          // not the same, so it becomes its own person/vehicle (like the
          // real matcher would)
          final list = data[group] as List;
          final kind = entity['kind'] as String;
          final name = kind[0].toUpperCase() + kind.substring(1);
          list.add({
            'entity_id': '${kind[0]}${list.length + 1}',
            'kind': kind,
            'label': '$name ${list.length + 1}',
            'description': 'from submission ${q['submission']}',
            'attributes': <String, dynamic>{},
            'cover': crops.isEmpty ? null : (crops.first as Map)['path'],
            'submission_count': 1,
            'crops': crops,
            'questions': [],
            'updated': [],
          });
        }
        data['open_questions'] = ((data['open_questions'] as num?) ?? 1) - 1;
        return;
      }
    }
  }

  @override
  bool get canCombine => true;

  @override
  Future<String> combine(int caseId, String fromId, String intoId) async {
    final data = await _sample();
    for (final group in ['people', 'vehicles', 'weapons']) {
      final list = data[group] as List;
      final from = list.cast<Map>().where((e) => e['entity_id'] == fromId).firstOrNull;
      final into = list.cast<Map>().where((e) => e['entity_id'] == intoId).firstOrNull;
      if (from == null || into == null) continue;
      (into['crops'] as List).addAll(from['crops'] as List);
      (into['questions'] as List? ?? []).addAll(from['questions'] as List? ?? []);
      into['submission_count'] = {
        for (final c in (into['crops'] as List)) (c as Map)['submission'],
      }.length;
      list.remove(from);
      return intoId;
    }
    throw StateError('Not found in this case any more.');
  }
}
